local ChapterRewardCgCellNode = Class('ChapterRewardCgCellNode')

function ChapterRewardCgCellNode:__init()
    self.data = nil
    self.position = nil
    self.cb = nil
end

function ChapterRewardCgCellNode:__delete()
    self.data = nil
    self.position = nil
    self.cb = nil
end

function ChapterRewardCgCellNode:Awake()
    CfUtils.SetActive(self.Content, true)
    SetButtonAction(self.Root, function()
        if self.cb then
            self.cb(self.data, self.position)
        end
    end)
    SetButtonAction(self.BtnPlay, function()
        ---Movie视频播放的逻辑
        if self.cb then
            self.cb(self.data, self.position)
        end
    end)
    self:PlayAnimByHide()
end

function ChapterRewardCgCellNode:PlayAnimByHide()
    CfUtils.PlayAnimation(self.controller, CELL_ANIM_NAME.HIDE)
end

function ChapterRewardCgCellNode:PlayAnimByIdle()
    CfUtils.PlayAnimation(self.controller, CELL_ANIM_NAME.IDLE)
end


function ChapterRewardCgCellNode:PlayDelayAnimByShow(delayIndex)
    CfUtils.PlayDelayShowAnimation(self.controller.gameObject, delayIndex, CELL_ANIM_NAME.SHOW, CELL_ANIM_NAME.WAIT)
end


function ChapterRewardCgCellNode:SetCellCallbackAction(cb)
    self.cb = cb
end

---FreshUI
---@param row TableML.TableFileRow
---@param position number
function ChapterRewardCgCellNode:FreshUI(row, position)
    self.position = position
    self.data = row
    if isSet(row, "isEmpty") then
        CfUtils.SetActive(self.Content, false)
        CfUtils.SetActive(self.Empty, true)
        return
    end
    CfUtils.SetActive(self.Empty, false)
    CfUtils.SetActive(self.Content, true)
    local unlockNum = checkNumber(row:Get("unlockNum"))
    local thumbnail = parse_pathName(row, "Image")
    local cgType = checkNumber(row:Get("cgType"))
    local cg = parse_pathName(row, "cg")
    local plotId = checkNumber(row:Get("plotId"))
    local video = string.format("Movie/%s", row:Get("video"))
    self.data = {
        unlockNum = unlockNum,
        thumbnail = thumbnail,
        cgType = cgType,
        cg = cg,
        plotId = plotId,
        video = video,
    }
    CfUtils.SetActive(self.BtnPlay, cgType == CG_TYPE.Movie)
    local isUnlock = QuestConfMgr:GetInstance():IsPassQuest(unlockNum)
    CfUtils.SetActive(self.ImgLock, not isUnlock)
    CfUtils.SetActive(self.Unlock, isUnlock)
    ---@type QuestMainVo
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(unlockNum)
    CfUtils.FillText(self.TextNumber, vo.label)
    if isUnlock then
        CfUtils.FillImage(self.ImgContent, thumbnail)
    end
end

function ChapterRewardCgCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ChapterRewardCgCellNode